result.output:
850					accumulators[checkpointID] = make(map[string]*checkpointAuthorAccumulator)
851				}
852				acc := accumulators[checkpointID][authorKey]
853				if acc == nil {
854					acc = &checkpointAuthorAccumulator{
855						Author:  author,
856						Commits: make(map[string]struct{}),
857					}
858					accumulators[checkpointID][authorKey] = acc
859				}
860				if _, ok := acc.Commits[commitSHA]; !ok {
861					acc.Commits[commitSHA] = struct{}{}
862					acc.Author.Commits++
863				}
864				if authoredAt.After(acc.LastCommitAt) {
865					acc.LastCommitAt = authoredAt.UTC()
866				}
867			}
868		}
869	
870		index := checkpointAuthorIndex{AuthorsByCheckpoint: make(map[string][]exportAuthor, len(accumulators))}
871		for checkpointID, byAuthor := range accumulators {
872			authors := make([]exportAuthor, 0, len(byAuthor))
873			for _, acc := range byAuthor {
874				author := acc.Author
875				if !acc.LastCommitAt.IsZero() {
876					lastCommitAt := acc.LastCommitAt
877					author.LastCommitAt = &lastCommitAt
878				}
879				authors = append(authors, author)
880			}
881			sort.Slice(authors, func(i, j int) bool {
882				if authors[i].Commits != authors[j].Commits {
883					return authors[i].Commits > authors[j].Commits
884				}
885				if authorLastCommitAt(authors[i]).Equal(authorLastCommitAt(authors[j])) {
886					return exportAuthorKey(authors[i]) < exportAuthorKey(authors[j])
887				}
888				return authorLastCommitAt(authors[i]).After(authorLastCommitAt(authors[j]))
889			})
890			index.AuthorsByCheckpoint[checkpointID] = authors
891		}
892		return index
893	}
