914			}
915			return listBranchCheckpoints(ctx, runner, repoDir, entireBinary, limit)
916		}
917	
918		checkpoints, warnings, err := listAllCheckpointRefs(ctx, runner, repoDir, limit)
919		if err != nil {
920			return nil, nil, err
921		}
922		if brainNoEgressMode() {
923			warnings = append(warnings, "no_egress: branch checkpoint fallback skipped")
924			return checkpoints, warnings, nil
925		}
926	
927		fallback, fallbackWarnings, fallbackErr := listAllRoutedCheckpoints(ctx, runner, repoDir, entireBinary, limit)
928		warnings = append(warnings, fallbackWarnings...)
929		scopeIncomplete := hasCheckpointScopeIncompleteWarning(fallbackWarnings)
930		if fallbackErr != nil {
931			if len(checkpoints) > 0 {
932				if scopeIncomplete {
933					warnings = append(warnings, checkpointScopeIncompleteCode+": routed checkpoint discovery failed after reporting partial scope; using locally enumerated ref names only")
934				} else {
935					warnings = append(warnings, "checkpoint_scope_incomplete: complete --search-all checkpoint discovery unavailable; using locally enumerated refs only: "+fallbackErr.Error())
936				}
937				return checkpoints, warnings, nil
938			}
939			if scopeIncomplete {
940				return nil, warnings, fmt.Errorf("%s: routed checkpoint discovery failed and no local checkpoint IDs were enumerable", checkpointScopeIncompleteCode)
941			}
942			return nil, warnings, fmt.Errorf("complete routed checkpoint discovery failed: %w", fallbackErr)
943		}
944		if scopeIncomplete && len(checkpoints) == 0 && len(fallback) == 0 {
945			return nil, warnings, fmt.Errorf("%s: Entire returned no readable checkpoint IDs from an incomplete persistent-store inventory", checkpointScopeIncompleteCode)
946		}
947		if !scopeIncomplete && len(checkpoints) == 0 {
948			warnings = append(warnings, "used Entire's complete routed checkpoint list because no local metadata refs were enumerable")
949		} else if !scopeIncomplete {
950			warnings = append(warnings, "combined locally enumerated checkpoint refs with Entire's complete routed checkpoint list")
951		}
