		}
		if err := json.Unmarshal([]byte(out), &report); err != nil {
			t.Fatalf("parse list json: %v\n%s", err, out)
		}
		if report.Open != 0 || len(report.Proposals) != 0 || report.QueueSupported {
			t.Fatalf("unsupported-queue list json = %+v", report)
		}
	}
}

